#include <bits/stdc++.h>
using namespace std;

const int INF = 0x3f3f3f3f;

struct Edge {
    int dest;
    int rev;
    int cap;
    int cost;
};

vector<Edge> graph[10001];
int visited[10001], current[10001], node_count;
int distance[10001], potential[10001];

int create_node() {
    return node_count++;
}

void add_edge(int u, int v, int cap, int cost) {
    graph[u].push_back({v, (int)graph[v].size(), cap, cost});
    graph[v].push_back({u, (int)graph[u].size() - 1, 0, -cost});
}

bool dijkstra(int s, int t) {
    fill(distance, distance + node_count, INF);
    fill(visited, visited + node_count, 0);
    using pii = pair<int, int>;
    priority_queue<pii, vector<pii>, greater<pii>> pq;
    pq.push({distance[s] = 0, s});
    while (!pq.empty()) {
        int du, u;
        tie(du, u) = pq.top(); pq.pop();
        if (visited[u]) continue;
        visited[u] = 1;
        for (auto& e : graph[u]) {
            int v = e.dest;
            int dv = du + potential[u] + e.cost - potential[v];
            if (!e.cap || visited[v] || distance[v] <= dv) continue;
            pq.push({distance[v] = dv, v});
        }
    }
    return visited[t];
}

bool bfs_layered(int s, int t) {
    fill(visited, visited + node_count, 0);
    queue<int> q;
    q.push(s);
    visited[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto& e : graph[u]) {
            int v = e.dest;
            if (visited[v] || !e.cap) continue;
            if (distance[v] != distance[u] + e.cost - potential[v] + potential[u]) continue;
            visited[v] = visited[u] + 1;
            q.push(v);
        }
    }
    return visited[t];
}

int dfs_flow(int u, int t, int f) {
    if (u == t) return f;
    int pushed = 0;
    for (int& i = current[u]; i < (int)graph[u].size(); ++i) {
        auto& e = graph[u][i];
        int v = e.dest;
        if (!e.cap || visited[v] != visited[u] + 1) continue;
        if (distance[v] != distance[u] + e.cost - potential[v] + potential[u]) continue;
        int df = dfs_flow(v, t, min(e.cap, f));
        pushed += df;
        f -= df;
        e.cap -= df;
        graph[v][e.rev].cap += df;
        if (!f) break;
    }
    return pushed;
}

pair<int, int> min_cost_flow(int s, int t, int max_flow) {
    int total_flow = 0, total_cost = 0;
    fill(potential, potential + node_count, 0);
    while (dijkstra(s, t)) {
        int flow = 0;
        while (bfs_layered(s, t)) {
            fill(current, current + node_count, 0);
            int df = dfs_flow(s, t, max_flow);
            max_flow -= df;
            flow += df;
            if (!max_flow) break;
        }
        total_flow += flow;
        total_cost += (distance[t] + potential[t]) * flow;
        for (int i = 0; i < node_count; ++i)
            potential[i] += distance[i];
        if (!max_flow) break;
    }
    return {total_flow, total_cost};
}

int main() {
    int n, m, k, c, d;
    scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
    int layers = max(n, k) * 2;
    node_count = 0;
    create_node();
    int source = create_node();
    int sink = create_node();
    for (int j = 0; j < k; ++j) {
        int a;
        scanf("%d", &a);
        --a;
        add_edge(source, a, 1, 0);
    }
    for (int z = 1; z <= m; ++z) {
        int u, v;
        scanf("%d %d", &u, &v);
        --u; --v;
        for (int i = 0; i + 1 < layers; ++i) {
            int u1 = u + i * n, v1 = v + (i + 1) * n;
            int u2 = u + (i + 1) * n, v2 = v + i * n;
            for (int j = 0; j < k; ++j) {
                add_edge(u1, v1, 1, c + d * (2 * j + 1));
                add_edge(v2, u2, 1, c + d * (2 * j + 1));
            }
        }
    }
    for (int i = 0; i + 1 < layers; ++i) {
        for (int j = 0; j < n; ++j) {
            int u = j + i * n, v = j + (i + 1) * n;
            add_edge(u, v, INF, c);
        }
    }
    for (int i = 0; i < layers; ++i)
        add_edge(i * n, sink, INF, 0);
    printf("%d\n", min_cost_flow(source, sink, INF).second);
    return 0;
}
